const message = $json.body?.message ?? $json.message ?? $json.text ?? "";
const regex = /[1-9A-HJ-NP-Za-km-z]{32,44}/g;
const matches = String(message).match(regex);

if (!matches || matches.length === 0) {
  return [{ json: { status: "ignored", reason: "No token address found" } }];
}

return [{
  json: {
    status: "parsed",
    tokenAddress: matches[0],
    sourceChannel: $json.body?.channel ?? $json.channel ?? "unknown",
    timestamp: Date.now(),
    rawMessage: String(message)
  }
}];

const LIMITS = {
  maxTradesPerDay: 200,
  maxOpenPositions: 3,
  dailyLossLimitUsd: -15,
  maxConsecutiveLosses: 15
};

const dailyPnL = Number($json.daily_pnl ?? 0);
const consecutiveLosses = Number($json.consecutive_losses ?? 0);
const tradesToday = Number($json.trades_today ?? 0);
const openPositions = Number($json.open_positions ?? 0);
const circuitBreakerActive = Boolean($json.circuit_breaker_active);
const duplicate = Boolean($json.duplicate);

if (duplicate) {
  return [{ json: { ...$json, status: "duplicate", reason: "Token seen in last 24h" } }];
}

if (circuitBreakerActive
    || dailyPnL <= LIMITS.dailyLossLimitUsd
    || consecutiveLosses >= LIMITS.maxConsecutiveLosses) {
  return [{ json: { ...$json, status: "circuit_breaker_active", reason: "Circuit breaker engaged" } }];
}

if (tradesToday >= LIMITS.maxTradesPerDay) {
  return [{ json: { ...$json, status: "daily_limit_reached", reason: "Daily trade limit reached" } }];
}

if (openPositions >= LIMITS.maxOpenPositions) {
  return [{ json: { ...$json, status: "queue", reason: "Open positions at cap" } }];
}

return [{
  json: {
    ...$json,
    status: "approved",
    dailyPnL,
    consecutiveLosses,
    tradesToday,
    openPositions
  }
}];

const tokenAddress = $json.tokenAddress;
const SECURITY_TIMEOUT_MS = 800;
const MARKET_TIMEOUT_MS = 5000;
const BIRDEYE_TIMEOUT_MS = 3000;
const RUGCHECK_MAX_SCORE = Number($env.RUGCHECK_MAX_SCORE ?? 500);
const SOLSNIFFER_MAX_TOP10_PCT = Number($env.SOLSNIFFER_MAX_TOP10_PCT ?? 25);

async function safeRequest(opts) {
  try {
    return await this.helpers.httpRequest(opts);
  } catch (err) {
    return { __error: err.message };
  }
}

const birdeyeKey = $env.BIRDEYE_API_KEY ?? "";
const birdeyeCall = birdeyeKey
  ? safeRequest.call(this, {
      url: `https://public-api.birdeye.so/defi/token_overview?address=${tokenAddress}`,
      method: "GET", json: true, timeout: BIRDEYE_TIMEOUT_MS,
      headers: { "X-API-KEY": birdeyeKey, "x-chain": "solana" }
    })
  : Promise.resolve({ __skipped: true });

const [rugcheckRaw, goplusRaw, sniffRaw, dexRaw, birdeyeRaw] = await Promise.all([
  safeRequest.call(this, {
    url: `https://api.rugcheck.xyz/v1/tokens/${tokenAddress}/report`,
    method: "GET", json: true, timeout: SECURITY_TIMEOUT_MS,
    headers: { Authorization: `Bearer ${$env.RUGCHECK_API_KEY ?? ""}` }
  }),
  safeRequest.call(this, {
    url: `https://api.gopluslabs.io/api/v1/token_security/solana?contract_addresses=${tokenAddress}`,
    method: "GET", json: true, timeout: SECURITY_TIMEOUT_MS,
    headers: { Authorization: `Bearer ${$env.GOPLUS_API_KEY ?? ""}` }
  }),
  safeRequest.call(this, {
    url: `https://api.solsniffer.com/v2/token/${tokenAddress}`,
    method: "GET", json: true, timeout: SECURITY_TIMEOUT_MS,
    headers: { "X-API-KEY": $env.SOLSNIFFER_API_KEY ?? "" }
  }),
  safeRequest.call(this, {
    url: `https://api.dexscreener.com/latest/dex/tokens/${tokenAddress}`,
    method: "GET", json: true, timeout: MARKET_TIMEOUT_MS
  }),
  birdeyeCall
]);

const securityResults = [];
if (!rugcheckRaw.__error) securityResults.push({ source: "rugcheck", ...rugcheckRaw });
if (!goplusRaw.__error)   securityResults.push({ source: "goplus", tokenAddress, ...goplusRaw });
if (!sniffRaw.__error)    securityResults.push({ source: "solsniffer", ...sniffRaw });

if (securityResults.length < 2) {
  return [{ json: { ...$json, status: "abort", reason: "Insufficient security data", failedAPIs: 3 - securityResults.length } }];
}

function isFalseLike(v) { return v === false || v === "0" || v === 0 || v === "false"; }

function evalResult(r) {
  if (r.source === "rugcheck") {
    return Number(r.score ?? Infinity) < RUGCHECK_MAX_SCORE && r.token?.liquidityBurned === true;
  }
  if (r.source === "goplus") {
    const data = r.data?.[tokenAddress] ?? r.data;
    return isFalseLike(data?.is_mintable) && isFalseLike(data?.is_freezable) && isFalseLike(data?.is_honeypot);
  }
  if (r.source === "solsniffer") {
    const top10 = Number(r.topHolders?.top10Percentage ?? r.top10Percentage ?? 100);
    return top10 <= SOLSNIFFER_MAX_TOP10_PCT;
  }
  return false;
}

const securityScore = Object.fromEntries(securityResults.map((r) => [r.source, evalResult(r)]));
const passedAll = Object.values(securityScore).every(Boolean);

if (!passedAll) {
  return [{ json: { ...$json, status: "abort", reason: "Security check failed", securityScore } }];
}

const pairs = Array.isArray(dexRaw?.pairs) ? dexRaw.pairs : [];
const pair = pairs
  .filter((p) => p.chainId === "solana")
  .sort((a, b) => Number(b.liquidity?.usd ?? 0) - Number(a.liquidity?.usd ?? 0))[0];

if (!pair || !(Number(pair.priceUsd) > 0)) {
  return [{ json: { ...$json, status: "abort", reason: "No DexScreener pair or price", securityScore } }];
}

const buys5m = Number(pair.txns?.m5?.buys ?? 0);
const sells5m = Number(pair.txns?.m5?.sells ?? 0);
const createdAt = Number(pair.pairCreatedAt ?? 0);

// Birdeye overrides DexScreener for holders/top10 when available (DexScreener
// rarely returns these fields, which collapses the learning pattern bucket).
const birdeyeData = birdeyeRaw && !birdeyeRaw.__error && !birdeyeRaw.__skipped
  ? (birdeyeRaw.data ?? birdeyeRaw)
  : null;

const holderCount = Number(
  birdeyeData?.holder ?? birdeyeData?.holderCount ?? pair.info?.holders ?? 0
);
const top10Pct = Number(
  birdeyeData?.top10HolderPercent ?? birdeyeData?.top10HolderPercentage ??
  pair.info?.top10HolderPercentage ?? 0
);

const market = {
  dexId: pair.dexId,
  pairAddress: pair.pairAddress,
  priceUsd: Number(pair.priceUsd ?? 0),
  liquidityUsd: Number(pair.liquidity?.usd ?? 0),
  volume5mUsd: Number(pair.volume?.m5 ?? 0),
  volume24hUsd: Number(pair.volume?.h24 ?? 0),
  holderCount,
  top10HolderPercentage: top10Pct,
  buyPressure: buys5m,
  sellPressure: sells5m,
  tokenAgeMinutes: createdAt > 0 ? Math.max(0, (Date.now() - createdAt) / 60000) : 0,
  holdersSource: birdeyeData ? "birdeye" : "dexscreener"
};

const features = {
  featureVersion: "v1.2",
  security: {
    rugcheck: !!securityScore.rugcheck,
    goplus: !!securityScore.goplus,
    solsniffer: !!securityScore.solsniffer
  },
  market,
  risk: { negativeCount: 0, source: "entry_snapshot" }
};

function bucket(value, thresholds) {
  const n = Number(value);
  for (const t of thresholds) if (n <= t) return `lte_${t}`;
  return `gt_${thresholds[thresholds.length - 1]}`;
}

const holdersBucket = market.holderCount > 0
  ? bucket(market.holderCount, [25, 75, 150, 300, 600])
  : "unknown";
const top10Bucket = market.top10HolderPercentage > 0 && market.top10HolderPercentage < 100
  ? bucket(market.top10HolderPercentage, [10, 20, 25, 35, 50])
  : "unknown";
const pressureRatio = market.sellPressure / (market.buyPressure || 1);

const patternKey = [
  `liq:${bucket(market.liquidityUsd, [1000, 5000, 10000, 25000, 50000])}`,
  `vol5:${bucket(market.volume5mUsd, [500, 2500, 5000, 10000, 25000])}`,
  `holders:${holdersBucket}`,
  `top10:${top10Bucket}`,
  `age:${bucket(market.tokenAgeMinutes, [5, 15, 30, 60, 180])}`,
  `sellbuy:${bucket(pressureRatio, [0.5, 1, 2, 3, 5])}`,
  `risk:0`
].join("|");

return [{
  json: {
    ...$json,
    status: "safe",
    securityScore,
    market,
    learningFeatures: features,
    patternKey,
    securitySnapshot: JSON.stringify(features.security),
    marketSnapshot: JSON.stringify(market),
    riskSnapshot: JSON.stringify(features.risk),
    entryPriceUsd: market.priceUsd,
    entryAvgVolume: market.volume24hUsd,
    entryPeakHolders: market.holderCount
  }
}];

// Limits — overridable via env (mirrors src/core/config.js DEFAULT_LIMITS).
const LIMITS = {
  baseBetUsd:          Number($env.BASE_BET_USD ?? 0.25),
  dailyLossLimitUsd:   Number($env.DAILY_LOSS_LIMIT_USD ?? -15),
  maxConsecutiveLosses: Number($env.MAX_CONSECUTIVE_LOSSES ?? 15),
  minBetUsd:           Number($env.MIN_BET_USD ?? 0.10),
  reduceLossThreshold: Number($env.REDUCE_LOSS_THRESHOLD ?? -10),
  hardReduceLossThreshold: Number($env.HARD_REDUCE_LOSS_THRESHOLD ?? -20)
};

const tokenAddress = $json.tokenAddress;
const dailyPnL = Number($json.dailyPnL ?? 0);
const consecutiveLosses = Number($json.consecutiveLosses ?? 0);
const sampleCount = Number($json.sample_count ?? 0);
const winCount = Number($json.win_count ?? 0);
const totalPnlUsd = Number($json.total_pnl_usd ?? 0);
const avgMaxMultiplier = Number($json.avg_max_multiplier ?? 0);
const entryPriceUsd = Number($json.entryPriceUsd ?? 0);

// --- Bet size (budget engine) ---
let betSizeUsd = LIMITS.baseBetUsd;
if (dailyPnL <= LIMITS.dailyLossLimitUsd || consecutiveLosses >= LIMITS.maxConsecutiveLosses) {
  return [{ json: { ...$json, status: "halt", action: "HALT", reason: "Circuit breaker activated", betSizeUsd: 0 } }];
}
if (dailyPnL < LIMITS.reduceLossThreshold) betSizeUsd = 0.15;
if (dailyPnL < LIMITS.hardReduceLossThreshold) betSizeUsd = LIMITS.minBetUsd;
if (consecutiveLosses >= 5)  betSizeUsd *= 0.8;
if (consecutiveLosses >= 10) betSizeUsd *= 0.5;

// --- Learning filter ---
let learningAction = "neutral";
let learningReason = "Insufficient samples";
let confidenceScore = 0;
if (sampleCount >= 5) {
  const winRate = winCount / sampleCount;
  const pnlPerTrade = totalPnlUsd / sampleCount;
  confidenceScore = Math.round(
    ((winRate - 0.5) * 2 + pnlPerTrade + Math.min(avgMaxMultiplier, 10) / 10) * 10000
  ) / 10000;
  if (confidenceScore <= -0.5) {
    learningAction = "reduce";
    learningReason = "Pattern has negative historical expectancy";
    betSizeUsd = Math.max(LIMITS.minBetUsd, betSizeUsd * 0.5);
  } else if (confidenceScore >= 0.8) {
    learningAction = "allow";
    learningReason = "Pattern has positive historical expectancy";
  }
}

betSizeUsd = Math.round(betSizeUsd * 100) / 100;

// --- Env / SOL price ---
const solUsd = Number($json.solUsd ?? $env.SOL_USD);
if (!Number.isFinite(solUsd) || solUsd <= 0) {
  return [{ json: { ...$json, status: "config_missing", reason: "Set SOL_USD env" } }];
}
const userPublicKey = $env.SOLANA_WALLET_PUBLIC_KEY;
if (!userPublicKey) {
  return [{ json: { ...$json, status: "config_missing", reason: "Set SOLANA_WALLET_PUBLIC_KEY env" } }];
}
if (!(entryPriceUsd > 0)) {
  return [{ json: { ...$json, status: "config_missing", reason: "entryPriceUsd missing" } }];
}

const lamportsAmount = Math.max(1, Math.floor((betSizeUsd / solUsd) * 1_000_000_000));
const slippageBps = Number($env.JUPITER_SLIPPAGE_BPS ?? 1500);

// --- Jupiter quote ---
let quote;
try {
  quote = await this.helpers.httpRequest({
    url: `https://quote-api.jup.ag/v6/quote?inputMint=So11111111111111111111111111111111111111112&outputMint=${tokenAddress}&amount=${lamportsAmount}&slippageBps=${slippageBps}`,
    method: "GET", json: true, timeout: 10000
  });
} catch (err) {
  return [{ json: { ...$json, status: "quote_failed", reason: err.message, betSizeUsd } }];
}

if (!quote?.outAmount || !quote?.inAmount) {
  return [{ json: { ...$json, status: "quote_failed", reason: "Jupiter returned no amounts", betSizeUsd } }];
}

// --- Jupiter swap build ---
let swapBuild;
try {
  swapBuild = await this.helpers.httpRequest({
    url: "https://quote-api.jup.ag/v6/swap",
    method: "POST", json: true, timeout: 15000,
    body: {
      quoteResponse: quote,
      userPublicKey,
      wrapAndUnwrapSol: true,
      dynamicComputeUnitLimit: true,
      prioritizationFeeLamports: {
        priorityLevelWithMaxLamports: {
          maxLamports: Number($env.JUPITER_MAX_PRIORITY_LAMPORTS ?? 10000000),
          priorityLevel: "veryHigh"
        }
      }
    }
  });
} catch (err) {
  return [{ json: { ...$json, status: "swap_build_failed", reason: err.message, betSizeUsd } }];
}

if (!swapBuild?.swapTransaction) {
  return [{ json: { ...$json, status: "swap_build_failed", reason: "No swapTransaction returned", betSizeUsd } }];
}

// --- Signer (paper mode if SIGNER_URL not set) ---
const signerUrl = $env.SIGNER_URL ?? "";

if (!signerUrl) {
  // Paper mode: flow through as "bought" so the position is recorded
  // and the monitor can manage it end-to-end without a real signer.
  return [{
    json: {
      ...$json,
      status: "bought",
      paperMode: true,
      reason: "SIGNER_URL not configured (paper mode)",
      betSizeUsd, learningAction, learningReason, confidenceScore,
      lamportsAmount,
      outputAmount: Number(quote.outAmount),
      entryPriceUsd,
      txHash: null,
      signedAt: Date.now()
    }
  }];
}

let signerResult;
try {
  signerResult = await this.helpers.httpRequest({
    url: signerUrl,
    method: "POST", json: true, timeout: 30000,
    headers: $env.SIGNER_API_KEY ? { Authorization: `Bearer ${$env.SIGNER_API_KEY}` } : {},
    body: {
      action: "buy",
      tokenAddress,
      serializedTransaction: swapBuild.swapTransaction,
      expectedOutputAmount: quote.outAmount
    }
  });
} catch (err) {
  return [{ json: { ...$json, status: "signer_failed", reason: err.message, betSizeUsd } }];
}

const txHash = signerResult?.txHash ?? signerResult?.signature ?? signerResult?.transactionHash;
if (!txHash) {
  return [{ json: { ...$json, status: "signer_failed", reason: "Signer returned no tx hash" } }];
}

return [{
  json: {
    ...$json,
    status: "bought",
    betSizeUsd, learningAction, learningReason, confidenceScore,
    lamportsAmount,
    outputAmount: Number(signerResult?.amount ?? quote.outAmount),
    entryPriceUsd,
    txHash,
    signedAt: Date.now()
  }
}];

// Runs in "Run Once for All Items" mode. Processes claimed positions in parallel.
const LIMITS = {
  hardStopFraction:    Number($env.HARD_STOP_FRACTION ?? 0.34),
  partialTpMultiplier: Number($env.PARTIAL_TP_MULTIPLIER ?? 2),
  partialTpFraction:   Number($env.PARTIAL_TP_FRACTION ?? 0.5),
  riskSignalThreshold: Number($env.RISK_SIGNAL_THRESHOLD ?? 3),
  volumeDeclineRatio:  Number($env.VOLUME_DECLINE_RATIO ?? 0.5),
  holderDropRatio:     Number($env.HOLDER_DROP_RATIO ?? 0.9),
  sellPressureRatio:   Number($env.SELL_PRESSURE_RATIO ?? 3)
};

const positions = items.map((it) => ({
  id: it.json.id,
  tokenAddress: it.json.token_address,
  entryPriceUsd: Number(it.json.entry_price),
  entryAmount: Number(it.json.entry_amount),
  betSizeUsd: Number(it.json.bet_size_usd ?? 0.25),
  highestPriceUsd: Number(it.json.highest_price ?? it.json.entry_price),
  partialTPTaken: Boolean(it.json.partial_tp_taken),
  avgVolume: Number(it.json.avg_volume ?? 0),
  peakHolders: Number(it.json.peak_holders ?? 0),
  paperMode: Boolean(it.json.paper_mode),
  createdAt: it.json.created_at
}));

const _h = this.helpers;
const _env = $env;

async function safeGet(url, timeout = 5000) {
  try { return await _h.httpRequest({ url, method: "GET", json: true, timeout }); }
  catch (err) { return { __error: err.message }; }
}

async function jupiterQuote(input, output, amount) {
  const slip = Number(_env.JUPITER_EXIT_SLIPPAGE_BPS ?? 2000);
  return safeGet(
    `https://quote-api.jup.ag/v6/quote?inputMint=${input}&outputMint=${output}&amount=${amount}&slippageBps=${slip}`,
    10000
  );
}

async function jupiterSwap(quote, userPublicKey) {
  try {
    return await _h.httpRequest({
      url: "https://quote-api.jup.ag/v6/swap",
      method: "POST", json: true, timeout: 15000,
      body: {
        quoteResponse: quote, userPublicKey,
        wrapAndUnwrapSol: true, dynamicComputeUnitLimit: true,
        prioritizationFeeLamports: {
          priorityLevelWithMaxLamports: {
            maxLamports: Number(_env.JUPITER_MAX_PRIORITY_LAMPORTS ?? 10000000),
            priorityLevel: "veryHigh"
          }
        }
      }
    });
  } catch (err) { return { __error: err.message }; }
}

async function callSigner(action, position, swapBuild, expectedOutputAmount) {
  const url = _env.SIGNER_URL ?? "";
  if (!url) return { __paper: true };
  try {
    return await _h.httpRequest({
      url, method: "POST", json: true, timeout: 30000,
      headers: _env.SIGNER_API_KEY ? { Authorization: `Bearer ${_env.SIGNER_API_KEY}` } : {},
      body: {
        action,
        tokenAddress: position.tokenAddress,
        serializedTransaction: swapBuild.swapTransaction,
        expectedOutputAmount,
        positionId: position.id
      }
    });
  } catch (err) { return { __error: err.message }; }
}

function classifyOutcome(finalMul, maxMul, pnl) {
  if (maxMul >= 10) return "moonshot";
  if (finalMul >= 2 || pnl > 0) return "winner";
  if (finalMul <= 0.34) return "hard_loss";
  if (pnl < 0) return "loser";
  return "flat";
}

async function processOne(position) {
  const userPublicKey = _env.SOLANA_WALLET_PUBLIC_KEY;
  const dexRaw = await safeGet(
    `https://api.dexscreener.com/latest/dex/tokens/${position.tokenAddress}`
  );

  if (dexRaw.__error) {
    return { positionId: position.id, shouldExit: false, shouldClose: false, reason: "market_fetch_failed" };
  }

  const pairs = Array.isArray(dexRaw?.pairs) ? dexRaw.pairs : [];
  const pair = pairs.filter((p) => p.chainId === "solana")
    .sort((a, b) => Number(b.liquidity?.usd ?? 0) - Number(a.liquidity?.usd ?? 0))[0];

  if (!pair || !(Number(pair.priceUsd) > 0)) {
    return { positionId: position.id, shouldExit: false, shouldClose: false, reason: "no_pair_or_price" };
  }

  const currentPriceUsd = Number(pair.priceUsd);
  const newHighest = Math.max(position.highestPriceUsd, currentPriceUsd);
  const multiplier = currentPriceUsd / position.entryPriceUsd;
  const buys5m = Number(pair.txns?.m5?.buys ?? 0);
  const sells5m = Number(pair.txns?.m5?.sells ?? 0);
  const volume24h = Number(pair.volume?.h24 ?? 0);
  const holders = Number(pair.info?.holders ?? 0);

  // --- Risk signals ---
  const signals = [];
  if (position.avgVolume > 0 && volume24h < position.avgVolume * LIMITS.volumeDeclineRatio)
    signals.push("volume_decline");
  if (position.peakHolders > 0 && holders > 0 && holders < position.peakHolders * LIMITS.holderDropRatio)
    signals.push("holder_drop");
  if ((sells5m / (buys5m || 1)) > LIMITS.sellPressureRatio) signals.push("sell_pressure_spike");

  // --- Decide exit action ---
  const stopLossPrice = position.entryPriceUsd * LIMITS.hardStopFraction;
  let action = "hold";
  let exitFraction = 0;
  let reason = "";

  if (signals.length >= LIMITS.riskSignalThreshold) {
    action = "panic_exit"; exitFraction = 1.0; reason = signals.join(", ");
  } else if (currentPriceUsd <= stopLossPrice) {
    action = "hard_stop_loss"; exitFraction = 1.0; reason = "below 66% stop";
  } else if (multiplier >= LIMITS.partialTpMultiplier && !position.partialTPTaken) {
    action = "partial_take_profit"; exitFraction = LIMITS.partialTpFraction; reason = `${LIMITS.partialTpMultiplier}x reached`;
  } else if (multiplier > LIMITS.partialTpMultiplier) {
    const pct = multiplier <= 10 ? 20 + (multiplier - 2) * 1.5
                                 : Math.min(32 + (multiplier - 10) * 2.5, 55);
    const trailPrice = newHighest * (1 - pct / 100);
    if (currentPriceUsd <= trailPrice) {
      action = "trailing_stop_exit"; exitFraction = 1.0; reason = `trail ${pct.toFixed(1)}%`;
    }
  }

  // --- Hold branch ---
  if (action === "hold") {
    return {
      positionId: position.id,
      tokenAddress: position.tokenAddress,
      shouldExit: false,
      shouldClose: false,
      highestPriceUsd: newHighest,
      currentPriceUsd,
      multiplier,
      paperMode: position.paperMode,
      signals
    };
  }

  // --- Need to sell: get sell quote/swap ---
  const sellAmount = Math.floor(position.entryAmount * exitFraction);
  if (sellAmount <= 0) {
    return { positionId: position.id, shouldExit: false, shouldClose: false, reason: "sell_amount_zero" };
  }

  const SOL_MINT = "So11111111111111111111111111111111111111112";
  const quote = await jupiterQuote(position.tokenAddress, SOL_MINT, sellAmount);
  if (quote.__error || !quote?.outAmount) {
    return { positionId: position.id, shouldExit: false, shouldClose: false, reason: "sell_quote_failed", error: quote.__error };
  }

  const swap = await jupiterSwap(quote, userPublicKey);
  if (swap.__error || !swap?.swapTransaction) {
    return { positionId: position.id, shouldExit: false, shouldClose: false, reason: "sell_swap_failed", error: swap.__error };
  }

  const signer = await callSigner("sell", position, swap, quote.outAmount);
  const txHash = signer?.__paper ? null : (signer?.txHash ?? signer?.signature ?? signer?.transactionHash);
  const paperMode = !!signer?.__paper;

  if (!paperMode && !txHash) {
    return { positionId: position.id, shouldExit: false, shouldClose: false, reason: "signer_failed", error: signer?.__error };
  }

  // --- PnL ---
  // Prefer exact signer numbers when present, fall back to a price-based estimate.
  // Signer contract (if implemented) returns:
  //   solReceivedLamports: bigint/number — actual SOL credited to the wallet
  //   feeLamports:         bigint/number — total network fees paid
  let pnlUsd;
  const solUsd = Number(_env.SOL_USD ?? 0);
  if (!paperMode && signer?.solReceivedLamports != null && solUsd > 0) {
    const solReceived = Number(signer.solReceivedLamports) / 1e9;
    const fees = Number(signer.feeLamports ?? 0) / 1e9;
    const usdReceived = (solReceived - fees) * solUsd;
    const usdSpentForThisSlice = position.betSizeUsd * exitFraction;
    pnlUsd = Math.round((usdReceived - usdSpentForThisSlice) * 100) / 100;
  } else {
    pnlUsd = Math.round(
      ((currentPriceUsd / position.entryPriceUsd - 1) * exitFraction * position.betSizeUsd) * 100
    ) / 100;
  }

  const finalMultiplier = multiplier;
  const maxMultiplier = newHighest / position.entryPriceUsd;
  const wasWinner = pnlUsd > 0 || finalMultiplier >= 2;
  const outcomeLabel = classifyOutcome(finalMultiplier, maxMultiplier, pnlUsd);
  const holdTimeSeconds = Math.max(0, Math.floor(
    (Date.now() - new Date(position.createdAt).getTime()) / 1000
  ));

  return {
    positionId: position.id,
    tokenAddress: position.tokenAddress,
    shouldExit: true,
    shouldClose: action !== "partial_take_profit",
    action,
    exitFraction,
    reason,
    exitPriceUsd: currentPriceUsd,
    highestPriceUsd: newHighest,
    multiplier,
    finalMultiplier,
    maxMultiplier,
    pnlUsd,
    wasWinner,
    outcomeLabel,
    holdTimeSeconds,
    entryPriceUsd: position.entryPriceUsd,
    sellAmount,
    txHash,
    paperMode: paperMode || position.paperMode,
    signals
  };
}

const results = await Promise.all(positions.map(async (p) => {
  try {
    return await processOne(p);
  } catch (err) {
    return {
      positionId: p.id,
      tokenAddress: p.tokenAddress,
      shouldExit: false,
      shouldClose: false,
      reason: "exception",
      error: String(err && err.message ? err.message : err)
    };
  }
}));
return results.map((r) => ({ json: r }));

const LIMITS = {
  dailyLossLimitUsd:    Number($env.DAILY_LOSS_LIMIT_USD ?? -15),
  maxConsecutiveLosses: Number($env.MAX_CONSECUTIVE_LOSSES ?? 15),
  apiFailuresThreshold: Number($env.API_FAILURES_THRESHOLD ?? 20),
  positionTimeoutMs:    Number($env.POSITION_TIMEOUT_MS ?? 45 * 60 * 1000)
};

const dailyPnL = Number($json.dailyPnL ?? 0);
const consecutiveLosses = Number($json.consecutiveLosses ?? 0);
const apiFailures = Number($json.apiFailures ?? 0);
const oldestOpenPositionAgeMs = Number($json.oldestOpenPositionAgeMs ?? 0);
const openPositionsCount = Number($json.openPositionsCount ?? 0);

const triggers = [
  { condition: dailyPnL <= LIMITS.dailyLossLimitUsd, reason: "Daily loss limit reached" },
  { condition: consecutiveLosses >= LIMITS.maxConsecutiveLosses, reason: "Consecutive losses limit" },
  { condition: apiFailures > LIMITS.apiFailuresThreshold, reason: "Excessive API failures" },
  { condition: oldestOpenPositionAgeMs > LIMITS.positionTimeoutMs, reason: "Position timeout risk" }
];

const trigger = triggers.find((t) => t.condition);

return [{
  json: {
    status: trigger ? "halted" : "healthy",
    circuitBreakerActive: !!trigger,
    circuitBreakerReason: trigger?.reason ?? null,
    dailyPnL,
    consecutiveLosses,
    apiFailures,
    oldestOpenPositionAgeMs,
    openPositionsCount
  }
}];
